import { Component, AfterViewInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { RideService } from '../../../core/services/ride.service';
import { VehicleType } from '../../../core/models/ride.model';

declare let L: any;

@Component({
  selector: 'app-home',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.scss']
})
export class HomeComponent implements AfterViewInit, OnDestroy {
  map: any;
  destinationQuery = '';
  selectedVehicle: VehicleType = 'MOTO';
  estimatedPrice: number = 5.0;
  isEstimating = false;

  // Selected or default coords (Tunis center)
  origin = { address: 'El Menzah, Tunis', lat: 36.8345, lng: 10.1800 };
  destination = { address: 'Avenue Habib Bourguiba, Centre Ville', lat: 36.8008, lng: 10.1865 };

  recentTrips = [
    { name: 'Avenue Habib Bourguiba', subtext: 'Centre Ville', price: '5 - 8 TND', lat: 36.8008, lng: 10.1865 },
    { name: 'La Marsa', subtext: 'Plage & Ville', price: '8 - 12 TND', lat: 36.8782, lng: 10.3247 }
  ];

  constructor(private rideService: RideService, private router: Router) {}

  ngAfterViewInit(): void {
    this.initMap();
  }

  ngOnDestroy(): void {
    if (this.map) {
      this.map.remove();
    }
  }

  private initMap(): void {
    if (typeof L === 'undefined') return;

    this.map = L.map('clientMap', {
      zoomControl: false,
      attributionControl: false
    }).setView([36.8150, 10.1800], 13);

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19
    }).addTo(this.map);

    // Custom yellow bike icon for MotoTaxi
    const motoIcon = L.divIcon({
      className: 'custom-moto-marker',
      html: `
        <div style="background: #F5C518; border-radius: 50%; width: 34px; height: 34px; display: flex; align-items: center; justify-content: center; box-shadow: 0 4px 10px rgba(0,0,0,0.2); border: 2px solid white;">
          <i class="fa-solid fa-location-arrow" style="color: #1A1A1A; font-size: 14px; transform: rotate(45deg);"></i>
        </div>
      `,
      iconSize: [34, 34],
      iconAnchor: [17, 17]
    });

    const destIcon = L.divIcon({
      className: 'custom-dest-marker',
      html: `
        <div style="background: white; border-radius: 50%; width: 28px; height: 28px; display: flex; align-items: center; justify-content: center; box-shadow: 0 4px 8px rgba(0,0,0,0.15); border: 2px solid #1A1A1A;">
          <i class="fa-solid fa-location-dot" style="color: #1A1A1A; font-size: 13px;"></i>
        </div>
      `,
      iconSize: [28, 28],
      iconAnchor: [14, 14]
    });

    L.marker([36.8180, 10.1750], { icon: motoIcon }).addTo(this.map);
    L.marker([36.8008, 10.1865], { icon: destIcon }).addTo(this.map);
    L.marker([36.8345, 10.1800], { icon: destIcon }).addTo(this.map);
  }

  selectVehicle(type: VehicleType) {
    this.selectedVehicle = type;
    if (type === 'MOTO') this.estimatedPrice = 5.0;
    else if (type === 'TAXI') this.estimatedPrice = 7.5;
    else if (type === 'EXPRESS') this.estimatedPrice = 9.0;
  }

  selectRecent(trip: any) {
    this.destinationQuery = trip.name;
    this.destination = { address: trip.name, lat: trip.lat, lng: trip.lng };
    if (this.selectedVehicle === 'MOTO') this.estimatedPrice = 6.5;
    else if (this.selectedVehicle === 'TAXI') this.estimatedPrice = 9.0;
    else if (this.selectedVehicle === 'EXPRESS') this.estimatedPrice = 11.0;
  }

  confirmBooking() {
    this.isEstimating = true;
    const req = {
      originAddress: this.origin.address,
      originLat: this.origin.lat,
      originLng: this.origin.lng,
      destAddress: this.destinationQuery || this.destination.address,
      destLat: this.destination.lat,
      destLng: this.destination.lng,
      vehicleType: this.selectedVehicle
    };

    this.rideService.requestRide(req).subscribe({
      next: (ride) => {
        this.isEstimating = false;
        this.router.navigate(['/client/tracking', ride.id]);
      },
      error: () => {
        // Fallback demo navigate if backend DB not running yet
        this.isEstimating = false;
        this.router.navigate(['/client/tracking', 101]);
      }
    });
  }
}
<div class="flex-1 flex flex-col relative h-full">

  <!-- Search Card Overlay on Map -->
  <div class="px-5 pt-2 pb-3 z-10">
    <div class="bg-white rounded-2xl shadow-lg p-2.5 flex items-center border border-gray-100 relative">
      <div class="w-10 flex items-center justify-center text-gray-400">
        <i class="fa-solid fa-magnifying-glass text-lg"></i>
      </div>
      <div class="flex-1 pr-3">
        <input 
          type="text" 
          [(ngModel)]="destinationQuery"
          placeholder="Où voulez-vous aller ?"
          class="w-full text-sm font-semibold text-gray-800 placeholder-gray-500 focus:outline-none bg-transparent">
        <span class="text-[11px] text-gray-400 block -mt-0.5" dir="rtl">وين تحب تمشي؟</span>
      </div>
      <button 
        (click)="confirmBooking()"
        class="w-11 h-11 rounded-full bg-[#F5C518] flex items-center justify-center text-gray-900 shadow-md hover:bg-[#E5B50A] transition">
        <i class="fa-solid fa-location-arrow text-base"></i>
      </button>
    </div>
  </div>

  <!-- Map Area (approx 45% height) -->
  <div class="relative w-full h-[280px] bg-gray-100">
    <div id="clientMap" class="w-full h-full"></div>
    <div class="absolute bottom-3 right-4 z-[400]">
      <button class="w-10 h-10 rounded-full bg-white shadow-md flex items-center justify-center text-gray-700 hover:bg-gray-50">
        <i class="fa-solid fa-crosshairs text-base"></i>
      </button>
    </div>
  </div>

  <!-- Bottom Panel (Recent Trips & Ride confirmation) -->
  <div class="flex-1 bg-white px-5 pt-4 pb-2 rounded-t-3xl -mt-4 z-10 shadow-[0_-8px_20px_rgba(0,0,0,0.04)] flex flex-col justify-between">

    <div>
      <!-- Section: Derniers trajets -->
      <div class="flex items-center justify-between mb-2">
        <div class="flex items-center gap-2">
          <i class="fa-regular fa-clock text-gray-500 text-sm"></i>
          <h2 class="text-sm font-bold text-gray-800">Derniers trajets</h2>
        </div>
        <span class="text-[11px] font-semibold text-gray-400">À partir de 5 TND</span>
      </div>

      <!-- Recent trips items -->
      <div class="space-y-2 mb-3">
        <div 
          *ngFor="let trip of recentTrips" 
          (click)="selectRecent(trip)"
          class="flex items-center justify-between p-2.5 rounded-xl hover:bg-gray-50 cursor-pointer transition border border-transparent hover:border-gray-100">
          <div class="flex items-center gap-3">
            <div class="w-8 h-8 rounded-full bg-gray-100 flex items-center justify-center text-gray-600">
              <i class="fa-solid fa-location-dot text-xs"></i>
            </div>
            <div>
              <p class="text-xs font-bold text-gray-900">{{ trip.name }}</p>
              <p class="text-[10px] text-gray-400">{{ trip.subtext }}</p>
            </div>
          </div>
          <span class="text-xs font-bold text-[#D4A000] bg-yellow-50 px-2.5 py-1 rounded-full border border-yellow-200">
            {{ trip.price }}
          </span>
        </div>
      </div>
    </div>

    <!-- Vehicle Selector and Confirm Button Bar -->
    <div class="pt-2 border-t border-gray-100 pb-1">
      <div class="grid grid-cols-4 gap-2 mb-2 items-center">
        <!-- Moto Card -->
        <button 
          (click)="selectVehicle('MOTO')"
          [class.border-[#F5C518]]="selectedVehicle === 'MOTO'"
          [class.bg-yellow-50]="selectedVehicle === 'MOTO'"
          class="p-2 border-2 border-gray-100 rounded-2xl flex flex-col items-center justify-center gap-1 transition">
          <i class="fa-solid fa-motorcycle text-lg text-gray-800"></i>
          <span class="text-[11px] font-bold text-gray-800">Moto</span>
        </button>

        <!-- Taxi Card -->
        <button 
          (click)="selectVehicle('TAXI')"
          [class.border-[#F5C518]]="selectedVehicle === 'TAXI'"
          [class.bg-yellow-50]="selectedVehicle === 'TAXI'"
          class="p-2 border-2 border-gray-100 rounded-2xl flex flex-col items-center justify-center gap-1 transition">
          <i class="fa-solid fa-taxi text-lg text-gray-800"></i>
          <span class="text-[11px] font-bold text-gray-800">Taxi</span>
        </button>

        <!-- Express Card -->
        <button 
          (click)="selectVehicle('EXPRESS')"
          [class.border-[#F5C518]]="selectedVehicle === 'EXPRESS'"
          [class.bg-yellow-50]="selectedVehicle === 'EXPRESS'"
          class="p-2 border-2 border-gray-100 rounded-2xl flex flex-col items-center justify-center gap-1 transition">
          <i class="fa-solid fa-truck-fast text-lg text-gray-800"></i>
          <span class="text-[11px] font-bold text-gray-800">Express</span>
        </button>

        <!-- Yellow Confirm Button -->
        <button 
          (click)="confirmBooking()"
          [disabled]="isEstimating"
          class="bg-[#F5C518] hover:bg-[#E5B50A] text-[#1A1A1A] font-extrabold p-2.5 rounded-2xl flex flex-col items-center justify-center shadow-md active:scale-95 transition h-full">
          <span class="text-[10px] leading-tight font-black uppercase tracking-wider">Confirmer</span>
          <span class="text-xs font-black">{{ estimatedPrice }} TND</span>
        </button>
      </div>
    </div>

  </div>

</div>
